 $('clipTextInput').value='';$('clipTextMode').value='append';$('clipTextMessage').textContent='';$('parseClipText').disabled=false;$('parseClipText').textContent='识别并填入';$('clipTextInput').disabled=false;$('clipTextMode').disabled=false;
