let storageInfo=null;
function renderStorage(data){storageInfo=data;const gb=n=>(n/1024**3).toFixed(2)+' GB';$('storageInfo').innerHTML=`<p>磁盘剩余：<strong>${gb(data.free_bytes)}</strong> / ${gb(data.total_bytes)}</p><p>基础剪辑缓存：${gb(data.cache_bytes)} · ${data.cleanup_count} 项</p><p>基础缓存上限：${gb(data.cache_limit_bytes)} · 最多保留 ${data.cache_days} 天</p><p>正片缓存上限：${gb(data.source_cache_limit_bytes)} · 磁盘预留：${gb(data.reserve_bytes)}</p><p class="hint">最多可清理 ${gb(data.cleanup_bytes)}，实际清理量会扣除正在使用或已变化的缓存。</p>`;$('cleanupCache').disabled=!data.cleanup_count}
